<script setup lang="ts">definePageMeta({ middleware: 'admin' }); const supabase=useSupabaseClient(); const rows=ref<any[]>([]); onMounted(async()=>{const{data}=await supabase.from('profiles').select('*').eq('role','teacher').order('last_name');rows.value=data||[]})</script>
<template><main class="mx-auto max-w-7xl px-4 py-8"><NuxtLink to="/admin" class="text-sm font-semibold text-blue-600">← Admin Dashboard</NuxtLink><h1 class="mt-3 text-3xl font-bold">Teachers</h1><div class="mt-6 overflow-hidden rounded-xl border bg-white"><div v-for="r in rows" :key="r.id" class="flex items-center border-b p-4"><div class="flex-1"><div class="font-semibold">{{r.first_name}} {{r.last_name}}</div><div class="text-sm text-slate-500">{{r.email}}</div></div><span>{{r.active?'Active':'Inactive'}}</span></div></div></main></template>
